/* ==========================================================
   FULL SCREEN COLOR-SHIFTING GRADIENT WITH BANNER
   ========================================================== */

/* 1. THE MOVING BACKGROUND LAYER
   Creates a full-screen canvas covering the page and cycling colors */
body::before {
    content: "";
    position: fixed;
    top: 0;
    left: 0;
    width: 100vw;
    height: 100vh;
    /* Broad spectrum color palette */
    background: linear-gradient(45deg, #ff3333, #ff9933, #33ffff, #9933ff, #33ff99, #3366ff) !important;
    background-size: 400% 400% !important;
    z-index: 10000; /* Placed over standard page layouts */
    
    /* Connects to the smooth infinite color transition below */
    animation: permanentSpectrumShift 20s ease-in-out infinite !important;
}

/* 2. THE TOP SYSTEM ANNOUNCEMENT BANNER
   Pins a static dark alert banner completely over the front layer */
body::after {
    content: "? SYSTEM ANNOUNCEMENT: get hacked (reversibal) ?";
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    background-color: #000000 !important;
    color: #ffffff !important;
    text-align: center;
    padding: 12px 24px;
    font-family: Arial, sans-serif;
    font-weight: bold;
    font-size: 15px;
    letter-spacing: 0.5px;
    z-index: 999999; /* Absolute highest layer to stay in the front */
    box-shadow: 0 4px 15px rgba(0, 0, 0, 0.5);
    border-bottom: 2px solid #333333;
    text-transform: uppercase;
    box-sizing: border-box;
}

/* 3. THE GRADIENT ANIMATION LOGIC
   Smoothly slides the gradient background to make the colors cycle */
@keyframes permanentSpectrumShift {
    0% {
        background-position: 0% 50% !important;
    }
    50% {
        background-position: 100% 50% !important;
    }
    100% {
        background-position: 0% 50% !important;
    }
}
